  // t("key", { name: value }) — the text, with {name} placeholders filled in.
  function t(key, vars) {
    var text = S[key];
    if (text === undefined) throw new Error("I18n: unknown key " + key);
    if (vars) {
      text = text.replace(/\{(\w+)\}/g, function (m, name) {
        return Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : m;
      });
    }
    return text;
  }

  return {
    LANGS: LANGS,
    LOCALES: LOCALES,
    NAMES: NAMES,
    STRINGS: S,
    t: t,
    lang: function () {
      return LANG;
    },
    locale: function (lang) {
      return LOCALES[lang || LANG] || LOCALES.en;
    },
    name: function (lang) {
      return NAMES[lang || LANG];
    },
  };
